import Case from "case";

import {
    ASTAliasedTypes,
    ASTArray,
    ASTDefinition,
    ASTEnum,
    ASTIntersection,
    ASTLiteral,
    ASTMap,
    ASTNode,
    ASTNodes,
    ASTObject,
    ASTTemplateTranslation,
    ASTUnion,
    NotTranspilerableTypeError,
    TExtendedTypeKind,
    Zod2X,
} from "@/core";

import { defaultOpts, IZod2DartOpt } from "./options";
import { getLibs } from "./libs";

/**
 * Transpiler for Zod schemas to Dart classes using package:json_annotation.
 *
 * The `.g.dart` part file is NOT generated by this transpiler — it must be produced
 * externally via `dart run build_runner build`.
 */
export class Zod2Dart extends Zod2X<IZod2DartOpt> {
    protected readonly commentKey = "//";

    protected lib;

    /**
     * Maps a local struct/class name to the discriminated union names it participates in.
     * Populated by a pre-scan of the AST before the normal transpile pass.
     */
    private _unionMembers = new Map<string, string[]>();

    /**
     * Names of locally-defined discriminated union abstract classes.
     * Used to emit @JsonKey(fromJson/toJson) when such a type appears as a field.
     */
    private _discriminatedUnionTypes = new Set<string>();

    /**
     * Names of typedef-emitted types (alias, union typedef, struct extends).
     * When these appear as field types in @JsonSerializable classes, we emit
     * @JsonKey(fromJson: TypeName.fromJson) to prevent json_serializable from
     * following the typedef chain and referencing transitive imports.
     */
    private _typedefNames = new Set<string>();

    /**
     * Maps a disc union typedef name (e.g. "NewDiscriminatedUnionItem") to the
     * fromJson function name of the underlying entity-level union
     * (e.g. "discriminatedUnionItemFromJson").
     * Populated during pre-scan when an ASTUnion node has aliasOf set.
     */
    private _discriminatedUnionDelegate = new Map<string, string>();

    /**
     * Types used for the templates of typedefs of generic types (local or imported), by typedef
     * name. E.g. "AdminUserEntity" → [{ aliasOf: "AdminUserMetadata", kind: "ASTObject" }].
     */
    private _typedefTemplates = new Map<string, ASTTemplateTranslation[]>();

    /**
     * Types used for the templates of fields of generic types of other files, by helper key.
     */
    private _usedCustomFromJsonTemplates = new Map<string, ASTTemplateTranslation[]>();

    /**
     * Unified set of type names needing custom @JsonKey annotations (discriminated unions use
     * their own <camelName>FromJson and <camelName>ToJson functions).
     * - Typedef types: fromJson = _<camelName>FromJson (standalone wrapper)
     * - TypedefList: list fromJson/toJson helpers
     * _toJson helpers are emitted in runAfter() for all entries.
     * Keyed by helper (`<typeName>` or `<typeName>[]` for list helpers), so a type used both
     * directly and in a list gets both helpers.
     */
    private _usedCustomFromJsonTypes = new Map<
        string,
        {
            typeName: string;
            kind:
                | "typedef"
                | "typedefList"
                | "discUnionList"
                | "discUnionMap"
                | "discUnionNullable";
            /** Base name of the functions of a discriminated union (`<fnBase>FromJson`). */
            fnBase?: string;
        }
    >();

    /**
     * Maps a type name (e.g. "GenericUserEntity") to its full Dart type with
     * template args (e.g. "GenericUserEntity<SomeDtoResult>"). Used in runAfter()
     * to generate helpers with correct generic return types and factory calls.
     */
    private _usedCustomFromJsonFullTypes = new Map<string, string>();

    /**
     * Maps a typedef name to its full extended type (the right-hand side of the
     * typedef). E.g. "AdminUserEntity" → "GenericUserEntity<AdminUserMetadata>".
     * Populated in addExtendedType() when the extended type has generic args.
     * Used in runAfter() to generate 2-arg fromJson calls for generic classes.
     */
    private _typedefToExtendedType = new Map<string, string>();

    constructor(opt: IZod2DartOpt = {}) {
        super({ ...defaultOpts, ...opt });
        this.lib = getLibs();
    }

    /**
     * Dart libraries can import each other.
     */
    override supportsCircularImports(): boolean {
        return true;
    }

    /**
     * Overrides transpile() to pre-scan discriminated union memberships before the normal pass.
     * This allows transpileStruct() to emit `implements UnionName` on member classes.
     */
    transpile(transpilerQueue: ASTNodes): string {
        this._unionMembers.clear();
        this._discriminatedUnionTypes.clear();
        this._typedefNames.clear();
        this._usedCustomFromJsonTypes.clear();
        this._usedCustomFromJsonFullTypes.clear();
        this._discriminatedUnionDelegate.clear();
        this._typedefToExtendedType.clear();
        this._typedefTemplates.clear();
        this._usedCustomFromJsonTemplates.clear();

        this._checkImportedNamesClash(transpilerQueue);

        transpilerQueue.nodes.forEach((node: ASTNode) => {
            if (node instanceof ASTUnion && node.discriminantKey) {
                // Track the union name for @JsonKey emission
                this._discriminatedUnionTypes.add(node.name);
                // If this is a typedef alias of another disc union (aliasOf set),
                // record which entity-level fromJson/toJson functions to delegate to.
                const aliasOf = (node as any).aliasOf as string | undefined;
                if (aliasOf) {
                    this._discriminatedUnionDelegate.set(node.name, Case.camel(aliasOf));
                }
                node.options.forEach((opt: ASTNode) => {
                    const name = (opt as any).name as string | undefined;
                    // Only track types local to this file (no parentFile = not imported)
                    if (name && !opt.parentFile) {
                        const existing = this._unionMembers.get(name) ?? [];
                        if (!existing.includes(node.name)) existing.push(node.name);
                        this._unionMembers.set(name, existing);
                    }
                });
            }

            // Detect cross-file nodes that are generic type instantiations:
            // e.g. AdminUserEntity (parentFile=app, genericOf="GenericUserEntity",
            // templatesTranslation=[{aliasOf:"AdminUserMetadata"}])
            // → store "AdminUserEntity" → "GenericUserEntity<AdminUserMetadata>" in
            //   _typedefToExtendedType so runAfter() can generate 2-arg fromJson helpers.
            if (
                node instanceof ASTObject &&
                node.parentFile &&
                node.genericOf &&
                node.templatesTranslation.length > 0
            ) {
                const typeArgs = node.templatesTranslation
                    .map((t) => (t.type !== undefined ? this.getAttributeType(t.type) : t.aliasOf))
                    .filter(Boolean)
                    .join(", ");
                if (typeArgs && node.name) {
                    this._typedefToExtendedType.set(node.name, `${node.genericOf}<${typeArgs}>`);
                    this._typedefTemplates.set(node.name, node.templatesTranslation);
                }
            }
        });

        return super.transpile(transpilerQueue);
    }

    /**
     * Dart imports are not prefixed, so a local type cannot share its name with an imported one.
     */
    private _checkImportedNamesClash(transpilerQueue: ASTNodes) {
        const localNames = new Set<string>();
        const importedNames = new Set<string>();

        transpilerQueue.nodes.forEach((node: ASTNode) => {
            const name = (node as any).name as string | undefined;
            if (name === undefined) {
                return;
            }

            if (node.parentFile !== undefined && node.aliasOf === undefined) {
                importedNames.add(name);
            } else {
                localNames.add(name);

                if (node.parentFile !== undefined) {
                    // Alias of an imported type.
                    importedNames.add(node.aliasOf!);
                }
            }
        });

        const clashes = [...localNames].filter((name) => importedNames.has(name));
        if (clashes.length > 0) {
            throw new NotTranspilerableTypeError(
                `Dart imports are not prefixed. Local types cannot share their name with ` +
                    `imported types: ${clashes.join(", ")}`
            );
        }
    }

    protected runBefore(): void {
        if (this.opt.useJsonSerialization !== false) {
            this.preImports.add(this.lib.jsonAnnotation);
            if (this.opt.partFile) {
                this.postImports.add(`part '${this.opt.partFile}.g.dart';`);
            }
        }
    }

    protected runAfter(): void {
        // Emit helper functions for field types that need custom @JsonKey annotations.
        // These helpers prevent json_serializable from following typedef chains and generating
        // code that references transitively-imported types not directly in scope.
        if (this.opt.useJsonSerialization !== false) {
            for (const {
                typeName,
                kind,
                fnBase: unionFn,
            } of this._usedCustomFromJsonTypes.values()) {
                const fnBase = Case.camel(typeName);

                if (kind === "discUnionList") {
                    this.push0(`List<${typeName}> _${fnBase}ListFromJson(Object? json) =>`);
                    this.push1(
                        `(json as List<dynamic>).map((e) => ${unionFn}FromJson(e as Map<String, dynamic>)).toList();\n`
                    );
                    this.push0(
                        `List<Map<String, dynamic>> _${fnBase}ListToJson(List<${typeName}> list) =>`
                    );
                    this.push1(`list.map(${unionFn}ToJson).toList();\n`);
                    continue;
                } else if (kind === "discUnionNullable") {
                    this.push0(
                        `Map<String, dynamic>? _${fnBase}NullableToJson(${typeName}? value) =>`
                    );
                    this.push1(`value == null ? null : ${unionFn}ToJson(value);\n`);
                    continue;
                } else if (kind === "discUnionMap") {
                    this.push0(`Map<String, ${typeName}> _${fnBase}MapFromJson(Object? json) =>`);
                    this.push1(
                        `(json as Map<String, dynamic>).map((k, e) => MapEntry(k, ${unionFn}FromJson(e as Map<String, dynamic>)));\n`
                    );
                    this.push0(
                        `Map<String, Map<String, dynamic>> _${fnBase}MapToJson(Map<String, ${typeName}> map) =>`
                    );
                    this.push1(`map.map((k, e) => MapEntry(k, ${unionFn}ToJson(e)));\n`);
                    continue;
                }

                // Types used for the templates of a generic field of another file (e.g.
                // GenericUserEntity<SomeDtoResult>) or of a typedef of a generic type (e.g.
                // AdminUserEntity = GenericUserEntity<AdminUserMetadata>).
                const fullType = this._usedCustomFromJsonFullTypes.get(typeName);
                const templates =
                    this._usedCustomFromJsonTemplates.get(typeName) ??
                    this._typedefTemplates.get(typeName);

                if (kind === "typedef") {
                    const extendedType = fullType ?? this._typedefToExtendedType.get(typeName);
                    const genericMatch = extendedType?.match(/^([^<]+)<(.+)>$/);
                    const valueType = fullType ?? typeName;

                    if (genericMatch) {
                        const fromJson = templates
                            ? this._genericFromJson(
                                  genericMatch[1],
                                  templates,
                                  "json as Map<String, dynamic>"
                              )
                            : `${genericMatch[1]}.fromJson(json as Map<String, dynamic>, (j) => ` +
                              `${genericMatch[2]}.fromJson(j as Map<String, dynamic>))`;
                        const toJson = templates
                            ? this._genericToJson("value", templates)
                            : `value.toJson((v) => v.toJson())`;
                        this.push0(`${valueType} _${fnBase}FromJson(Object? json) =>`);
                        this.push1(`${fromJson};\n`);
                        this.push0(`Map<String, dynamic> _${fnBase}ToJson(${valueType} value) =>`);
                        this.push1(`${toJson};\n`);
                    } else {
                        // Non-generic class: simple fromJson + toJson helpers
                        this.push0(`${typeName} _${fnBase}FromJson(Object? json) =>`);
                        this.push1(`${typeName}.fromJson(json as Map<String, dynamic>);\n`);
                        this.push0(`Map<String, dynamic> _${fnBase}ToJson(${typeName} value) =>`);
                        this.push1(`(value as dynamic).toJson() as Map<String, dynamic>;\n`);
                    }
                } else if (kind === "typedefList") {
                    // List<typedef>: list fromJson + toJson helpers
                    const fromJson = templates
                        ? this._genericFromJson(typeName, templates, "e as Map<String, dynamic>")
                        : `${typeName}.fromJson(e as Map<String, dynamic>)`;
                    const toJson = templates
                        ? this._genericToJson("e", templates)
                        : `(e as dynamic).toJson() as Map<String, dynamic>`;
                    this.push0(`List<${typeName}> _${fnBase}ListFromJson(Object? json) =>`);
                    this.push1(`(json as List<dynamic>).map((e) => ${fromJson}).toList();\n`);
                    this.push0(
                        `List<Map<String, dynamic>> _${fnBase}ListToJson(List<${typeName}> list) =>`
                    );
                    this.push1(`list.map((e) => ${toJson}).toList();\n`);
                }
            }
        }
        this._usedCustomFromJsonTypes.clear();
        this._usedCustomFromJsonFullTypes.clear();
        this._usedCustomFromJsonTemplates.clear();
    }

    // ── Import / namespace ──────────────────────────────────────────────────

    protected addImportFromFile(filename: string, _namespace: string): string {
        const base = filename.endsWith(".dart") ? filename.slice(0, -5) : filename;
        return `import './${base}.dart';`;
    }

    protected getTypeFromExternalNamespace(_namespace: string, typeName: string): string {
        return typeName;
    }

    // ── Generics ────────────────────────────────────────────────────────────

    // ── Layered modeling ────────────────────────────────────────────────────

    /**
     * For Layered Modeling. Language options used to declare a type that extends another one.
     */
    protected getExtendedTypeOptions(data: ASTNode, type?: TExtendedTypeKind) {
        const isStruct =
            data instanceof ASTObject ||
            (data instanceof ASTIntersection && data.newObject !== undefined);

        const translatedTemplates = this.getGenericTemplatesTranslation(data);
        if (translatedTemplates && data.name && data instanceof ASTObject) {
            this._typedefTemplates.set(data.name, data.templatesTranslation);
        }

        return {
            type: isStruct ? undefined : (type as "union" | "alias" | undefined),
            templates: translatedTemplates || undefined,
            declaredTemplates:
                !translatedTemplates && data instanceof ASTObject && data.templates.size > 0
                    ? `<${[...data.templates].join(", ")}>`
                    : undefined,
        };
    }

    protected addExtendedType(
        name: string,
        parentNamespace: string,
        aliasOf: string,
        opt?: {
            type?: "union" | "alias";
            isInternal?: boolean;
            templates?: string;
            declaredTemplates?: string;
        }
    ): void {
        const extendedType = opt?.isInternal
            ? aliasOf
            : this.getTypeFromExternalNamespace(parentNamespace, aliasOf);

        const templates = opt?.templates ?? "";
        const declaredTemplates = opt?.declaredTemplates ?? "";

        if (opt?.type === "alias" || opt?.type === "union") {
            this._typedefNames.add(name);
            this.push0(`typedef ${name}${declaredTemplates} = ${extendedType}${templates};\n`);
        } else {
            // Dart 3: use typedef for empty class extensions to keep json_serializable happy.
            // `class B extends A {}` without @JsonSerializable is rejected by build_runner.
            // A typedef is valid Dart 3 syntax and correctly aliases the type for serialization.
            this._typedefNames.add(name);
            this.push0(`typedef ${name}${declaredTemplates} = ${extendedType}${templates};\n`);
        }
        // Track generic extended types so runAfter() can generate 2-arg fromJson calls.
        const fullExtended = `${extendedType}${templates ?? ""}`;
        if (fullExtended.includes("<")) {
            this._typedefToExtendedType.set(name, fullExtended);
        }
    }

    // ── Primitive type methods ──────────────────────────────────────────────

    protected getStringType = (): string => "String";
    protected getBooleanType = (): string => "bool";
    protected getAnyType = (): string => "dynamic";
    protected getDateType = (): string => "DateTime";

    protected getNumberType(isInt: boolean, _range: { min?: number; max?: number }): string {
        // Dart has a single `int` type regardless of range
        return isInt ? "int" : "double";
    }

    /**
     * Returns the Dart type for a literal value.
     * Dart has no structural literal types, so we return the underlying primitive type.
     * When a parent enum is provided, returns the enum type name (not a member expression),
     * since Dart enum members cannot be used as types.
     */
    protected getLiteralStringType(
        value: string | number | boolean,
        parentEnumNameKey?: [string, string]
    ): string | number {
        if (parentEnumNameKey) {
            // Return the enum type name only — member access is not a valid Dart type
            return parentEnumNameKey[0];
        }
        if (typeof value === "boolean") return "bool";
        if (typeof value === "number") {
            return Number.isInteger(value) ? "int" : "double";
        }
        return "String";
    }

    // ── Composite type methods ──────────────────────────────────────────────

    /** Ex: List<List<T>> for 2D array */
    protected getArrayType(arrayType: string, arrayDeep: number): string {
        let output = `List<${arrayType}>`;
        for (let i = 0; i < arrayDeep - 1; i++) {
            output = `List<${output}>`;
        }
        return output;
    }

    /** Ex: Set<T> */
    protected getSetType = (itemType: string): string => `Set<${itemType}>`;

    /** Ex: Map<K, V> */
    protected getMapType = (keyType: string, valueType: string): string =>
        `Map<${keyType}, ${valueType}>`;

    /** Ex: Map<String, V> (record key is always String) */
    protected getRecordType = (keyType: string, valueType: string): string =>
        `Map<${keyType}, ${valueType}>`;

    /** Ex: (T1, T2, T3) — Dart 3 positional record type */
    protected getTupleType = (itemsType: string[]): string => `(${itemsType.join(", ")})`;

    /** Dart has no native union type; use Object */
    protected getUnionType = (_itemsType: string[]): string => "Object";

    /** Dart has no native intersection type; use Object */
    protected getIntersectionType = (_itemsType: string[]): string => "Object";

    // ── Transpile methods ───────────────────────────────────────────────────

    protected transpileAliasedType(data: ASTAliasedTypes): void {
        if (this.checkExtendedTypeInclusion(data, "alias")) return;

        this.addComment(data.description);

        let resolvedType: string;
        if (data instanceof ASTArray) {
            resolvedType = this.getAttributeType(data.item);
        } else {
            resolvedType = this.getAttributeType(data);
        }

        this.push0(`typedef ${data.name} = ${resolvedType};\n`);
    }

    /**
     * Emits a Dart enhanced enum with a typed `value` field and `@JsonEnum` annotation.
     *
     * All-string values:
     *   @JsonEnum(valueField: 'value')
     *   enum EnumItem {
     *     enum1('Enum1'),
     *     enum2('Enum2');
     *
     *     const EnumItem(this.value);
     *     final String value;
     *   }
     *
     * Mixed (int + string): typedef alias with comment.
     */
    protected transpileEnum(data: ASTEnum): void {
        if (this.checkExtendedTypeInclusion(data, "alias")) return;

        this.addComment(data.description);

        const allStrings = data.values.every(([, v]) => typeof v === "string");
        const allInts = data.values.every(([, v]) => typeof v === "number");

        if (allStrings || allInts) {
            const valueType = allStrings ? "String" : "int";
            const q = allStrings ? "'" : "";

            if (this.opt.useJsonSerialization !== false) {
                this.push0(`@JsonEnum(valueField: 'value')`);
            }
            this.push0(`enum ${data.name} {`);

            data.values.forEach(([key, value], index) => {
                const memberName = Case.camel(key);
                const comma = index < data.values.length - 1 ? "," : ";";
                this.push1(`${memberName}(${q}${value}${q})${comma}`);
            });

            this.push0("");
            this.push1(`const ${data.name}(this.value);`);
            this.push1(`final ${valueType} value;`);
            this.push0(`}\n`);
        } else {
            // Mixed-type enum: fall back to typedef alias + comment
            this.push0(`typedef ${data.name} = dynamic;`);
            this.push0(`// ${data.name}: mixed-type enum — no single Dart base type`);
            data.values.forEach(([key, value]) => {
                const constName = Case.camel(key);
                const v = typeof value === "string" ? `'${value}'` : `${value}`;
                this.push0(`// const ${constName} = ${v};`);
            });
            this.push0("");
        }
    }

    protected transpileStruct(data: ASTObject): void {
        if (this.checkExtendedTypeInclusion(data)) return;

        this.addComment(data.description);
        this._transpileStructBody(data);
    }

    /**
     * Dart intersection:
     * - If the AST produced a merged `newObject`, emit it as a flat class.
     * - Otherwise emit a typedef alias to Object with a comment.
     */
    protected transpileIntersection(data: ASTIntersection): void {
        if (this.checkExtendedTypeInclusion(data)) return;

        this.addComment(data.description);

        if (data.newObject) {
            this._transpileStructBody(data.newObject);
        } else {
            const leftType = this.getAttributeType(data.left);
            const rightType = this.getAttributeType(data.right);
            this.push0(
                `typedef ${data.name} = Object; // Intersection of: ${leftType}, ${rightType}\n`
            );
        }
    }

    /**
     * Dart union:
     * - Non-discriminated: typedef alias to Object with a comment listing member types.
     * - Discriminated: abstract base class + factory unmarshal function using Dart 3 switch,
     *   and a function that serializes it.
     *
     * Classes of other files cannot implement the union, so these variants are wrapped in
     * local classes that do (`class AnyEventCreated implements AnyEvent { final Created value; }`).
     */
    protected transpileUnion(data: ASTUnion): void {
        if (this.checkExtendedTypeInclusion(data, "union")) return;

        this.addComment(data.description);

        const optionNames = data.options.map(this.getAttributeType.bind(this));

        if (!data.discriminantKey) {
            this.push0(`// ${data.name} is a union of: ${optionNames.join(", ")}`);
            this.push0(`typedef ${data.name} = Object;\n`);
            return;
        }

        const useJson = this.opt.useJsonSerialization !== false;
        const options = data.options.map((opt, i) => {
            const discriminantValue = (opt as ASTDefinition).constraints?.discriminantValue as
                | string
                | undefined;
            const baseName = optionNames[i].replace(/<.*$/, "");
            return {
                typeName: optionNames[i],
                discriminantValue,
                templates: this._getInstanceTemplates(opt),
                wrapper: opt.parentFile
                    ? `${data.name}${Case.pascal(String(discriminantValue ?? baseName))}`
                    : undefined,
            };
        });

        this.push0(`// Discriminated union on '${data.discriminantKey}'.`);
        this.push0(`// Possible types: ${options.map((o) => o.wrapper ?? o.typeName).join(", ")}`);
        this.push0(`abstract class ${data.name} {}\n`);

        for (const opt of options.filter((o) => o.wrapper !== undefined)) {
            this.push0(`/// ${data.name} variant of ${opt.typeName}, declared in another file.`);
            this.push0(`class ${opt.wrapper} implements ${data.name} {`);
            this.push1(`final ${opt.typeName} value;\n`);
            this.push1(`const ${opt.wrapper}(this.value);`);
            if (useJson) {
                const toJson = opt.templates
                    ? this._genericToJson("value", opt.templates)
                    : "value.toJson()";
                this.push0("");
                this.push1(`Map<String, dynamic> toJson() => ${toJson};`);
            }
            this.push0(`}\n`);
        }

        // Emit factory unmarshal function when all members have a discriminant value
        const allHaveDiscriminantValue = options.every((o) => o.discriminantValue !== undefined);

        if (allHaveDiscriminantValue && useJson) {
            const fnName = Case.camel(data.name);
            this.push0(`${data.name} ${fnName}FromJson(Map<String, dynamic> json) {`);
            this.push1(`return switch (json['${data.discriminantKey}']) {`);

            for (const opt of options) {
                const dv = opt.discriminantValue!;
                const isNumber = !isNaN(Number(dv));
                const isBool = dv === "true" || dv === "false";
                const caseVal = isNumber || isBool ? dv : `'${dv}'`;
                // Generic types use the factory with one fromJson function per template:
                // Foo.fromJson(json, (j) => Bar..., (j) => Baz...)
                const genericMatch = opt.typeName.match(/^([^<]+)<(.+)>$/);
                let value: string;
                if (opt.templates) {
                    const typeName = genericMatch ? genericMatch[1] : opt.typeName;
                    value = this._genericFromJson(typeName, opt.templates, "json");
                } else if (genericMatch) {
                    value =
                        `${genericMatch[1]}.fromJson(json, (j) => ` +
                        `${genericMatch[2]}.fromJson(j as Map<String, dynamic>))`;
                } else {
                    value = `${opt.typeName}.fromJson(json)`;
                }
                this.push2(`${caseVal} => ${opt.wrapper ? `${opt.wrapper}(${value})` : value},`);
            }

            const escapedKey = data.discriminantKey.replace(/"/g, '\\"');
            this.push2(
                `_ => throw Exception("Unknown ${data.name} discriminant: \${json['${escapedKey}']}")`
            );
            this.push1(`};`);
            this.push0(`}\n`);

            // Instances of generic types need the functions that serialize their templates.
            const genericOptions = options.filter((o) => o.templates && !o.wrapper);
            const toJsonSignature = `Map<String, dynamic> ${fnName}ToJson(${data.name} value) =>`;
            if (genericOptions.length === 0) {
                this.push0(toJsonSignature);
                this.push1(`(value as dynamic).toJson() as Map<String, dynamic>;\n`);
            } else {
                this.push0(`${toJsonSignature} switch (value) {`);
                for (const opt of genericOptions) {
                    this.push1(`${opt.typeName} x => ${this._genericToJson("x", opt.templates!)},`);
                }
                this.push1(`_ => (value as dynamic).toJson() as Map<String, dynamic>,`);
                this.push0(`};\n`);
            }
        }
    }

    // ── Private helpers ─────────────────────────────────────────────────────

    /**
     * Returns the functions that deserialize and serialize the type used for a template of a
     * generic type (the `fromJsonT` and `toJsonT` arguments of json_serializable).
     */
    private _templateJson(template: ASTTemplateTranslation): { fromJson: string; toJson: string } {
        const type = template.type;
        const typeName = type ? this.getAttributeType(type) : template.aliasOf!;

        if (
            (type instanceof ASTLiteral && type.parentEnum !== undefined) ||
            template.kind === ASTEnum.kind
        ) {
            // Enums are serialized by their value (@JsonEnum(valueField: 'value')).
            return {
                fromJson: `(j) => ${typeName}.values.firstWhere((e) => e.value == j)`,
                toJson: `(v) => v.value`,
            };
        }

        if (type === undefined || type instanceof ASTDefinition) {
            if (template.kind === ASTUnion.kind && this._discriminatedUnionTypes.has(typeName)) {
                const fnBase = Case.camel(typeName);
                return {
                    fromJson: `(j) => ${fnBase}FromJson(j as Map<String, dynamic>)`,
                    toJson: `(v) => ${fnBase}ToJson(v)`,
                };
            }
            return {
                fromJson: `(j) => ${typeName}.fromJson(j as Map<String, dynamic>)`,
                toJson: `(v) => v.toJson()`,
            };
        }

        switch (typeName) {
            case "int":
                return { fromJson: `(j) => (j as num).toInt()`, toJson: `(v) => v` };
            case "double":
                return { fromJson: `(j) => (j as num).toDouble()`, toJson: `(v) => v` };
            case "DateTime":
                return {
                    fromJson: `(j) => DateTime.parse(j as String)`,
                    toJson: `(v) => v.toIso8601String()`,
                };
            case "dynamic":
                return { fromJson: `(j) => j`, toJson: `(v) => v` };
            default:
                return { fromJson: `(j) => j as ${typeName}`, toJson: `(v) => v` };
        }
    }

    /** Ex: Message.fromJson(json, (j) => ..., (j) => ...) */
    private _genericFromJson(
        typeName: string,
        templates: ASTTemplateTranslation[],
        json: string
    ): string {
        const fns = templates.map((t) => this._templateJson(t).fromJson);
        return `${typeName}.fromJson(${[json, ...fns].join(", ")})`;
    }

    /** Ex: value.toJson((v) => ..., (v) => ...) */
    private _genericToJson(value: string, templates: ASTTemplateTranslation[]): string {
        return `${value}.toJson(${templates.map((t) => this._templateJson(t).toJson).join(", ")})`;
    }

    /**
     * Returns the types used for the templates of a type that is an instance of a generic type
     * (directly or through a typedef), if any.
     */
    private _getInstanceTemplates(node: ASTNode): ASTTemplateTranslation[] | undefined {
        const templates =
            node instanceof ASTDefinition && node.templatesTranslation.length > 0
                ? node.templatesTranslation
                : this._typedefTemplates.get(node.name ?? "");
        return templates !== undefined && templates.length > 0 ? templates : undefined;
    }

    /** Renders the full body of a Dart class for an ASTObject. */
    private _transpileStructBody(data: ASTObject): void {
        const isGeneric = data.templates.size > 0;
        const templateStr = isGeneric ? `<${[...data.templates].join(", ")}>` : "";

        const unionNames = this._unionMembers.get(data.name ?? "") ?? [];
        const implementsClause =
            unionNames.length > 0 ? ` implements ${unionNames.join(", ")}` : "";

        const useJson = this.opt.useJsonSerialization !== false;

        if (useJson) {
            if (isGeneric) {
                this.push0(
                    `@JsonSerializable(explicitToJson: true, genericArgumentFactories: true)`
                );
            } else {
                this.push0(`@JsonSerializable(explicitToJson: true)`);
            }
        }

        this.push0(`class ${data.name}${templateStr}${implementsClause} {`);

        const properties = Object.entries(data.properties);

        if (properties.length === 0) {
            this.push0(`}`);
            if (useJson) {
                this._emitFromToJson(data);
            }
            this.push0("");
            return;
        }

        // Field declarations
        for (const [key, value] of properties) {
            this._transpileMember(key, value);
        }

        // Constructor
        this.push0("");
        this.push1(`${data.name}({`);
        for (const [key, value] of properties) {
            const fieldName = this.opt.keepKeys === true ? key : Case.camel(key);
            const isOpt = value.isOptional || value.isNullable;
            if (isOpt) {
                this.push2(`this.${fieldName},`);
            } else {
                this.push2(`required this.${fieldName},`);
            }
        }
        this.push1(`});`);

        if (useJson) {
            this._emitFromToJson(data);
        }

        this.push0(`}\n`);
    }

    /** Renders a single class field declaration with optional `@JsonKey` annotation. */
    private _transpileMember(key: string, memberNode: ASTNode): void {
        const fieldName = this.opt.keepKeys === true ? key : Case.camel(key);
        const isOpt = memberNode.isOptional || memberNode.isNullable;
        const varType = this.getAttributeType(memberNode);

        if (memberNode.description && !memberNode.name && !this.isTranspilerable(memberNode)) {
            this.addComment(memberNode.description, this.indent[1]);
        }

        const useJson = this.opt.useJsonSerialization !== false;
        let annotationEmitted = false;

        if (useJson) {
            // Only @JsonSerializable classes (ASTObject) need @JsonKey to prevent json_serializable
            // from following the typedef chain to a type not directly imported.
            // Primitives (String, int, double, bool, DateTime), collections (List, Map, Set,
            // Tuple), enums, and dynamic are all handled natively by json_serializable.
            const instanceType: string | undefined = (memberNode as any).instanceType;
            const isClassLike = instanceType === ASTObject.kind;

            // Cross-file reference that is a class-like type: needs @JsonKey wrapper.
            const memberIsAlias = (memberNode as any).parentFile !== undefined && isClassLike;
            const isList = ((memberNode as any).arrayDimension ?? 0) > 0;
            // Actual type name (before array/optional wrapping)
            const nodeName: string | undefined = (memberNode as any).name;

            const baseType = varType.replace(/\?$/, "").replace(/^List<(.+)>$/, "$1");
            const localTypeName = baseType.includes(".") ? baseType.split(".").pop()! : baseType;

            // Discriminated unions are abstract classes: they use the fromJson/toJson functions
            // of the union. If the union is a typedef alias of another (aliasOf set), the
            // functions of the entity-level union are used, as none are defined for the alias.
            const unionFnBase = (name: string) =>
                this._discriminatedUnionDelegate.get(name) ?? Case.camel(name);
            const mapValue =
                memberNode instanceof ASTMap &&
                !memberNode.arrayDimension &&
                memberNode.value instanceof ASTDefinition &&
                !memberNode.value.arrayDimension &&
                this.getAttributeType(memberNode.key) === "String"
                    ? memberNode.value.name
                    : undefined;

            if (
                isList &&
                (memberNode as any).arrayDimension === 1 &&
                this._discriminatedUnionTypes.has(localTypeName)
            ) {
                // List of a discriminated union: list helpers that use its functions.
                this._usedCustomFromJsonTypes.set(`${localTypeName}[]`, {
                    typeName: localTypeName,
                    kind: "discUnionList",
                    fnBase: unionFnBase(localTypeName),
                });
                const fnBase = Case.camel(localTypeName);
                const namePart = fieldName !== key ? `name: '${key}', ` : "";
                this.push1(
                    `@JsonKey(${namePart}fromJson: _${fnBase}ListFromJson, toJson: _${fnBase}ListToJson)`
                );
                annotationEmitted = true;
            } else if (mapValue !== undefined && this._discriminatedUnionTypes.has(mapValue)) {
                // Record of a discriminated union: map helpers that use its functions.
                this._usedCustomFromJsonTypes.set(`${mapValue}{}`, {
                    typeName: mapValue,
                    kind: "discUnionMap",
                    fnBase: unionFnBase(mapValue),
                });
                const fnBase = Case.camel(mapValue);
                const namePart = fieldName !== key ? `name: '${key}', ` : "";
                this.push1(
                    `@JsonKey(${namePart}fromJson: _${fnBase}MapFromJson, toJson: _${fnBase}MapToJson)`
                );
                annotationEmitted = true;
            } else if (this._discriminatedUnionTypes.has(localTypeName) && !isList) {
                const fnBase = unionFnBase(localTypeName);
                const namePart = fieldName !== key ? `name: '${key}', ` : "";
                // toJson functions must accept the type of the field, also when it is nullable.
                let toJson = `${fnBase}ToJson`;
                if (isOpt) {
                    this._usedCustomFromJsonTypes.set(`${localTypeName}?`, {
                        typeName: localTypeName,
                        kind: "discUnionNullable",
                        fnBase,
                    });
                    toJson = `_${Case.camel(localTypeName)}NullableToJson`;
                }
                this.push1(`@JsonKey(${namePart}fromJson: ${fnBase}FromJson, toJson: ${toJson})`);
                annotationEmitted = true;
            } else if (this._typedefNames.has(localTypeName) && !isList && isClassLike) {
                // Locally-defined typedef of a class — use standalone fromJson helper to
                // prevent json_serializable from following the chain to an un-imported type.
                this._usedCustomFromJsonTypes.set(localTypeName, {
                    typeName: localTypeName,
                    kind: "typedef",
                });
                const fnBase = Case.camel(localTypeName);
                const namePart = fieldName !== key ? `name: '${key}', ` : "";
                this.push1(
                    `@JsonKey(${namePart}fromJson: _${fnBase}FromJson, toJson: _${fnBase}ToJson)`
                );
                annotationEmitted = true;
            } else if (memberIsAlias) {
                // Cross-file class alias not in _typedefNames — same treatment (including lists).
                const typeName = nodeName || localTypeName;
                const fnBase = Case.camel(typeName);
                const kind = isList ? "typedefList" : "typedef";
                this._usedCustomFromJsonTypes.set(isList ? `${typeName}[]` : typeName, {
                    typeName,
                    kind,
                });
                // Store full type (including generics) for helper generation in runAfter().
                // List helpers only use the type of the items.
                const fullType = varType.replace(/\?$/, "");
                if (!isList && fullType !== typeName) {
                    this._usedCustomFromJsonFullTypes.set(typeName, fullType);
                    const templates = this._getInstanceTemplates(memberNode);
                    if (templates) {
                        this._usedCustomFromJsonTemplates.set(typeName, templates);
                    }
                }
                const namePart = fieldName !== key ? `name: '${key}', ` : "";
                if (isList) {
                    this.push1(
                        `@JsonKey(${namePart}fromJson: _${fnBase}ListFromJson, toJson: _${fnBase}ListToJson)`
                    );
                } else {
                    this.push1(
                        `@JsonKey(${namePart}fromJson: _${fnBase}FromJson, toJson: _${fnBase}ToJson)`
                    );
                }
                annotationEmitted = true;
            }
        }

        if (!annotationEmitted && fieldName !== key) {
            // @JsonKey is needed when the Dart field name differs from the original JSON key
            this.push1(`@JsonKey(name: '${key}')`);
        }

        const typeStr = isOpt ? `${varType}?` : varType;
        this.push1(`final ${typeStr} ${fieldName};`);
    }

    /**
     * Emits `fromJson` factory and `toJson` method delegation stubs.
     * For generic classes, extra `fromJsonT` / `toJsonT` function parameters are added
     * as required by `json_serializable` with `genericArgumentFactories: true`.
     */
    private _emitFromToJson(data: ASTObject): void {
        const className = data.name!;
        const templates = [...data.templates];
        const isGeneric = templates.length > 0;

        if (isGeneric) {
            const fromParams = templates
                .map((t) => `${t} Function(Object? json) fromJson${t}`)
                .join(", ");
            const toParams = templates
                .map((t) => `Object? Function(${t} value) toJson${t}`)
                .join(", ");
            const fromArgs = templates.map((t) => `fromJson${t}`).join(", ");
            const toArgs = templates.map((t) => `toJson${t}`).join(", ");

            this.push0("");
            this.push1(
                `factory ${className}.fromJson(Map<String, dynamic> json, ${fromParams}) =>`
            );
            this.push2(`_\$${className}FromJson(json, ${fromArgs});`);
            this.push0("");
            this.push1(`Map<String, dynamic> toJson(${toParams}) =>`);
            this.push2(`_\$${className}ToJson(this, ${toArgs});`);
        } else {
            this.push0("");
            this.push1(`factory ${className}.fromJson(Map<String, dynamic> json) =>`);
            this.push2(`_\$${className}FromJson(json);`);
            this.push0("");
            this.push1(`Map<String, dynamic> toJson() => _\$${className}ToJson(this);`);
        }
    }
}
